// kaya runtime for C# guests: loading, the direct-ring occurrence loop,
// and submit. Hand-written; the wire vocabulary next to it
// (KayaWire.cs) is generated by kaya-bindgen.
//
// The direct tier: C# reads the occurrence ring with Volatile loads and
// stores — P/Invoke is crossed only to start the core, to wait on an
// empty ring, and to submit. The consumer contract is the io_uring
// recipe documented in kaya.h.

using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
using System.Threading;

/// One file the picker answered with: a handle to redeem, a display
/// name, and LocalPath — a RE-OPENABLE NAME, empty unless re-opening it
/// actually works, which measurement puts at the three desktops and
/// neither phone (DESIGN.md, File dialogs).
public readonly record struct PickedFile(ulong Handle, string Name, string LocalPath)
{
    /// Redeem the handle for a real FileStream, plus whether it seeks.
    ///
    /// BLOCKS, and may block for a long time, so call it from a thread
    /// you chose and post the result back. kaya is not in the data
    /// path: the stream returned is a real file.
    ///
    /// Seekable RIDES THE OPEN rather than the pick because that is the
    /// only place the answer exists — an Android provider may hand back
    /// a pipe, and nothing short of opening reveals it.
    public (FileStream File, bool Seekable) Open(uint mode = 0)
        => Kaya.OpenPicked(Handle, mode);
}

/// One representation, arriving — the sum a copy is the record of.
/// C# has records and pattern matching, so this is an abstract record
/// with one derived record per constructor and a `switch` expression is
/// the elimination.
///
/// YOU OFFER MANY AND YOU RECEIVE ONE, and the two shapes say so: a
/// record of five optional fields would invite a guest to check five
/// where four are structurally always empty.
abstract record Representation
{
    public sealed record Text(string Value) : Representation;

    public sealed record Html(string Value) : Representation;

    /// Encoded image bytes. WHAT COMES BACK MAY BE A RE-ENCODE — the
    /// hosts convert freely between image types — so compare what the
    /// image IS, never the bytes it arrived in.
    public sealed record Image(byte[] Bytes) : Representation;

    /// Files, plural INSIDE one representation — the same nesting
    /// text/uri-list and CF_HDROP already have. A pasted file is the
    /// picker's own capability arriving through a second door, so it
    /// opens with the call that already exists.
    public sealed record Files(List<PickedFile> Value) : Representation;

    /// An app-defined format, round-tripped verbatim.
    public sealed record Custom(string Id, byte[] Bytes) : Representation;

    /// Turn the decoder's kind-and-values into the sum, or null.
    ///
    /// EMPTY IS THE UNIVERSAL NO: null covers a denied prompt on iOS, an
    /// unfocused reader on Android or Wayland, an empty clipboard, and
    /// content in no representation this read accepted. The guest is not
    /// told which, because the platforms deliberately do not say.
    internal static Representation? From(KayaWire.ClipValues? clip)
    {
        if (clip == null) return null;
        string Str(int i) => i < clip.Values.Count && clip.Values[i] is string s ? s : "";
        byte[] Blob(int i) =>
            i < clip.Values.Count && clip.Values[i] is byte[] b ? b : Array.Empty<byte>();
        switch (clip.Kind)
        {
            case KayaWire.ClipText: return new Text(Str(0));
            case KayaWire.ClipHtml: return new Html(Str(0));
            case KayaWire.ClipImage: return new Image(Blob(0));
            case KayaWire.ClipCustom: return new Custom(Str(0), Blob(1));
            case KayaWire.ClipFiles:
                // The picker's own three-per-file grouping, so a guest
                // that decodes a dialog result decodes this with the
                // same loop.
                var files = new List<PickedFile>();
                for (int i = 0; i + 2 < clip.Values.Count; i += 3)
                {
                    long handle = clip.Values[i] is long h ? h : 0;
                    files.Add(new PickedFile((ulong)handle, Str(i + 1), Str(i + 2)));
                }
                return new Files(files);
            default: return null;
        }
    }
}

static class Kaya
{
    [StructLayout(LayoutKind.Sequential)]
    struct RingInfo
    {
        public IntPtr Data;
        public uint Capacity;
        public IntPtr Head;
        public IntPtr Tail;
    }

    [DllImport("kaya")]
    static extern int kaya_run();

    [DllImport("kaya")]
    static extern void kaya_occurrence_ring(out RingInfo info);

    [DllImport("kaya")]
    [return: MarshalAs(UnmanagedType.I1)]
    static extern bool kaya_wait_occurrences();

    [DllImport("kaya")]
    static extern void kaya_wake();

    /// Return the app thread from WaitOccurrences. Safe from any thread;
    /// the binding calls it from KayaApp.Post, and guests do not name it.
    public static void Wake() => kaya_wake();

    /// Block until there MAY be something to do: a record arrived, or
    /// another thread called Wake. False once the core has shut down.
    /// "May" is the honest word — a wake returns true with the ring
    /// still empty, and the caller re-checks both sources, which a
    /// drain-then-poll loop does anyway.
    public static bool WaitOccurrences() => kaya_wait_occurrences();

    [DllImport("kaya")]
    static extern void kaya_submit(byte[] records, nuint len);

    [DllImport("kaya")]
    static extern ulong kaya_blob_register(byte[] bytes, nuint len);

    [DllImport("kaya")]
    static extern IntPtr kaya_occurrence_blob(ulong handle, out nuint len);

    [DllImport("kaya")]
    static extern void kaya_occurrence_blob_release(ulong handle);

    /// Redeem an occurrence blob for its bytes, and release it. Called
    /// by the generated decoder, never by a guest.
    ///
    /// COPY THEN RELEASE, in that order: the pointer borrows core memory
    /// that the release frees. A blob arriving in an OCCURRENCE is a
    /// handle into a table with no boundary that retires one — unlike
    /// the apply channel's batch-local index, which the next batch
    /// supersedes — so the decoder is what has to let go of it, while
    /// decoding, before any handle can reach an app. Release is
    /// idempotent, so a dead handle costs nothing.
    public static byte[] OccurrenceBlob(ulong handle)
    {
        IntPtr data = kaya_occurrence_blob(handle, out nuint len);
        byte[] bytes = System.Array.Empty<byte>();
        if (data != IntPtr.Zero && len > 0)
        {
            bytes = new byte[(int)len];
            Marshal.Copy(data, bytes, 0, (int)len);
        }
        kaya_occurrence_blob_release(handle);
        return bytes;
    }

    [DllImport("kaya")]
    static extern int kaya_open_picked(
        ulong handle, uint mode, out long raw, out uint seekable);

    /// Redeem a picked handle for a real FileStream, plus whether it
    /// seeks. BLOCKS, and may block for a long time — a cloud provider
    /// can download the file before it answers — so call it from a
    /// thread you chose and post the result back (DESIGN.md, File
    /// dialogs).
    ///
    /// THE HANDLE BECOMES .NET'S. SafeFileHandle is constructed with
    /// ownsHandle: true, so disposing the stream closes it exactly once
    /// and the core keeps no claim. The core hands back the OS's own
    /// handle — a descriptor on POSIX, a HANDLE on Windows — precisely
    /// so each runtime converts it with its own file API rather than
    /// through a CRT descriptor only the minting CRT would accept, and
    /// SafeFileHandle takes both.
    public static (FileStream File, bool Seekable) OpenPicked(ulong handle, uint mode)
    {
        int rc = kaya_open_picked(handle, mode, out long raw, out uint seekable);
        if (rc != 0)
            throw new IOException($"kaya: opening the picked file failed (code {rc})");
        var access = mode switch
        {
            0 => FileAccess.Read,
            1 => FileAccess.Write,
            _ => FileAccess.ReadWrite,
        };
        var safe = new SafeFileHandle((IntPtr)raw, ownsHandle: true);
        return (new FileStream(safe, access), seekable != 0);
    }

    static RingInfo ring;

    /// On Windows, "kaya" resolves to kaya.dll via PATH. Elsewhere, point
    /// KAYA_LIB at the built library (e.g. target/debug/libkaya.dylib).
    /// Call once, before anything else.
    public static void Init()
    {
        NativeLibrary.SetDllImportResolver(typeof(Kaya).Assembly, (name, _, _) =>
        {
            string env = Environment.GetEnvironmentVariable("KAYA_LIB");
            if (name == "kaya" && env != null && NativeLibrary.TryLoad(env, out IntPtr handle))
                return handle;
            return IntPtr.Zero;
        });
        kaya_occurrence_ring(out ring);
    }

    /// Enter the core on the calling thread (which must be the process
    /// main thread); returns the exit code when the app ends.
    [DllImport("kaya")]
    static extern ulong kaya_spec_hash();

    public static int Run()
    {
        // The stale-artifact guard: this binding was generated from one
        // spec revision; the loaded library must speak the same one.
        if (kaya_spec_hash() != KayaWire.SpecHash)
            throw new InvalidOperationException(
                $"kaya: library speaks spec 0x{kaya_spec_hash():x16}, this binding was " +
                $"generated from 0x{KayaWire.SpecHash:x16} — rebuild the library or " +
                "regenerate bindings");
        return kaya_run();
    }

    /// Submit one transaction: the concatenation of packed records
    /// (KayaWire.Tx* results), applied atomically.
    public static void Submit(params byte[][] records)
    {
        int len = 0;
        foreach (byte[] r in records) len += r.Length;
        byte[] tx = new byte[len];
        int at = 0;
        foreach (byte[] r in records)
        {
            r.CopyTo(tx, at);
            at += r.Length;
        }
        kaya_submit(tx, (nuint)tx.Length);
    }

    /// Register bulk payload bytes (an encoded image) with the core:
    /// one copy into core-owned memory, returning the u64 handle the
    /// next submit from this guest consumes, referenced or not. The
    /// caller's bytes are free to drop the moment this returns.
    public static ulong RegisterBlob(byte[] data) =>
        kaya_blob_register(data, (nuint)data.Length);

    /// Block for the next occurrence; false when the core has shut
    /// down. keys is empty when id is a widget id, else id is a
    /// template node id and keys is the stamped copy's key path,
    /// outermost first. payload carries the entry's new text (string)
    /// for OccKindTextChanged, the checkbox's new state (bool) for
    /// OccKindToggled, null for clicks.
    /// Read the next occurrence if one is ready, WITHOUT blocking;
    /// false means the ring is empty right now.
    ///
    /// Polling and waiting are separate calls, rather than one blocking
    /// NextOccurrence, because the app thread has a SECOND source of
    /// work: closures posted from other threads. A single blocking read
    /// would park inside C with no way back out to drain them.
    public static unsafe bool PollOccurrence(
        out ushort kind, out ulong id, out List<object> keys, out object payload)
    {
        uint* head = (uint*)ring.Head;
        uint* tail = (uint*)ring.Tail;
        byte* data = (byte*)ring.Data;
        uint mask = ring.Capacity - 1;

        uint h = Volatile.Read(ref *head);
        while (true)
        {
            uint t = Volatile.Read(ref *tail); // acquire: records below are visible
            if (h == t)
            {
                kind = 0;
                id = 0;
                keys = new List<object>();
                payload = null;
                return false; // nothing ready; the caller waits
            }
            byte* at = data + (h & mask);
            uint size = *(uint*)at;
            byte[] rec = new byte[size];
            Marshal.Copy((IntPtr)at, rec, 0, (int)size);
            bool valid = KayaWire.ParseOccurrence(rec, out kind, out id, out keys, out payload);
            h += size;
            Volatile.Write(ref *head, h); // release: hand the space back
            if (valid)
                return true;
        }
    }
}
